[{"order":1,"type":"heading","text":"Data Validation and Sanitization in Express.js (express-validator, Joi)"},{"order":2,"type":"paragraph","text":"In any robust backend application, accepting raw, unverified user input is a major security risk. Data validation ensures that the incoming payload matches the expected business rules, while data sanitization cleans the input to prevent malicious injections such as XSS or NoSQL injection. In this tutorial, we will explore two of the most popular libraries for data validation and sanitization in Express.js: express-validator and Joi."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"First, initialize a new Node.js project and install Express along with both validation libraries."},{"order":5,"type":"code","text":"npm init -y
npm install express express-validator joi"},{"order":6,"type":"subheading","text":"Method 1: Using express-validator"},{"order":7,"type":"paragraph","text":"express-validator is a set of Express middleware that wraps validator.js functions. It allows you to chain validation and sanitization rules directly inside your route definitions."},{"order":8,"type":"code","text":"const express = require('express');
const { body, validationResult } = require('express-validator');
const app = express();

app.use(express.json());

app.post('/api/user-express', [
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 6 }),
  body('age').optional().isInt({ min: 18 })
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  res.status(200).json({ message: 'Validation passed using express-validator!' });
});

app.listen(3000, () => console.log('Server running on port 3000'));"},{"order":9,"type":"subheading","text":"Method 2: Using Joi"},{"order":10,"type":"paragraph","text":"Joi is a powerful schema description language and data validator for JavaScript. It allows you to create explicit blueprints for your data separate from your route logic, keeping your controllers clean and testable."},{"order":11,"type":"code","text":"const express = require('express');
const Joi = require('joi');
const app = express();

app.use(express.json());

const userSchema = Joi.object({
  email: Joi.string().email().required(),
  password: Joi.string().min(6).required(),
  age: Joi.number().integer().min(18)
});

const validateJoi = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.body, { abortEarly: false });
    if (error) {
      const errorMessage = error.details.map((detail) => detail.message).join(', ');
      return res.status(400).json({ error: errorMessage });
    }
    req.sanitizedBody = value;
    next();
  };
};

app.post('/api/user-joi', validateJoi(userSchema), (req, res) => {
  res.status(200).json({ message: 'Validation passed using Joi!', data: req.sanitizedBody });
});"},{"order":12,"type":"subheading","text":"Key Differences and Best Practices"},{"order":13,"type":"bullet_point","text":"express-validator integrates tightly with Express middleware and excels at chaining sanitizers and validators per field."},{"order":14,"type":"bullet_point","text":"Joi provides decoupled, highly reusable schema definitions that can be shared between frontend and backend or used for non-HTTP objects."},{"order":15,"type":"bullet_point","text":"Always sanitize inputs (trimming whitespace, escaping HTML characters, normalizing emails) before processing or saving them to databases."}]
